import { requestLocator } from './isAbsoluteURL.js';

/**
 * Creates a new URL by combining the specified URLs
 *
 * @param {string} baseURL The base URL
 * @param {string} relativeURL The relative URL
 *
 * @returns {string} The combined URL
 */
export default function combineURLs(baseURL, relativeURL) {
  return requestLocator.joinBaseAndRelative(baseURL, relativeURL);
}

export function composeFullPath(baseURL, requestedURL) {
  return requestLocator.composeFullPath(baseURL, requestedURL);
}

export function appendSerializedParams(url, params, options) {
  return requestLocator.appendSerializedParams(url, params, options);
}

export function assembleLocator(baseURL, url, params, paramsSerializer) {
  return requestLocator.assembleLocator(baseURL, url, params, paramsSerializer);
}

